(3481,37,'_menu','field_olea_event_menu'),
(3482,40,'_pingme','1'),
(3483,40,'_encloseme','1'),
(3484,40,'meta_title',''),
(3485,40,'_meta_title','field_olea_post_meta_title'),
(3486,40,'intro','Covent Garden feels especially lively during the festive season. It\'s a place to meet before an evening out, catch up with friends and make time for a proper celebration. At Olea Social, Christmas dining begins with Mediterranean food and the pleasure of sharing a table.\n\nLocated on Upper St Martin\'s Lane, a short walk from Covent Garden and Leicester Square, Olea Social is well placed for a Christmas lunch, dinner or group gathering in central London.'),
(3487,40,'_intro','field_olea_post_intro'),
(3488,40,'outro','Planning a festive gathering? Explore Olea Social\'s menus and send an enquiry.'),
(3489,40,'_outro','field_olea_post_outro'),
