(3500,42,'_meta_title','field_olea_post_meta_title'),
(3501,42,'intro','The best part of Christmas is getting everyone together. The friends you have been meaning to catch up with, the colleagues who have shared a busy year, the family you never quite get enough time with.\n\nAt Olea Social, we love being part of those moments. This festive season, we invite you to gather around our table, enjoy our food and make time for each other.'),
(3502,42,'_intro','field_olea_post_intro'),
(3503,42,'outro','Plan your Christmas gathering at Olea Social'),
